import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadWadiyarData(){const e=readFileSync(resolve(__dirname,"../../krishnaraja-wadiyar-iv-explorer/wadiyar-data.js"),"utf-8");return new Function(e+"\nreturn { WADIYAR_INFO, EDUCATION_INSTITUTIONS, INFRASTRUCTURE_PROJECTS, CULTURAL_HERITAGE, TIMELINE_EVENTS, REFERENCES };")()}describe("Krishnaraja Wadiyar IV Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadWadiyarData()}),describe("WADIYAR_INFO metadata",()=>{it("contains correct Krishnaraja Wadiyar IV metadata and reign",()=>{expect(e.WADIYAR_INFO.id).toBe("krishnaraja-wadiyar-iv"),expect(e.WADIYAR_INFO.title).toContain("Krishnaraja Wadiyar IV"),expect(e.WADIYAR_INFO.dynasty).toContain("Wadiyar"),expect(e.WADIYAR_INFO.honorific).toContain("Rajarshi")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.WADIYAR_INFO.quickStats)).toBe(!0),expect(e.WADIYAR_INFO.quickStats.length).toBe(6)})}),describe("EDUCATION_INSTITUTIONS & INFRASTRUCTURE_PROJECTS",()=>{it("contains IISc land grant, University of Mysore, and KRS Dam details",()=>{expect(Array.isArray(e.EDUCATION_INSTITUTIONS)).toBe(!0),expect(e.EDUCATION_INSTITUTIONS.length).toBeGreaterThanOrEqual(3);const a=e.EDUCATION_INSTITUTIONS.find(e=>e.name.includes("IISc"));expect(a).toBeDefined(),expect(Array.isArray(e.INFRASTRUCTURE_PROJECTS)).toBe(!0),expect(e.INFRASTRUCTURE_PROJECTS.length).toBeGreaterThanOrEqual(3)})}),describe("TIMELINE_EVENTS & REFERENCES",()=>{it("contains reign timeline and reference citations",()=>{expect(Array.isArray(e.TIMELINE_EVENTS)).toBe(!0),expect(e.TIMELINE_EVENTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});